const items = $input.all();
if (items.length !== 1) throw new Error('CONFIG_INVALID: run one monitor at a time.');
const c = items[0].json;
if (typeof c.symbol !== 'string' || !/^[A-Z0-9]{1,20}$/.test(c.symbol)) throw new Error('CONFIG_INVALID: symbol.');
const ranges = {maxAgeSeconds:[1,3600],maxFutureSkewSeconds:[0,60],minConfidence:[0,1],maxDispersionBps:[0,10000],minSources:[1,1000]};
for (const [key,[min,max]] of Object.entries(ranges)) {
 if (typeof c[key] !== 'number' || !Number.isFinite(c[key]) || c[key] < min || c[key] > max) throw new Error('CONFIG_INVALID: policy number.');
}
if (!Number.isInteger(c.minSources)) throw new Error('CONFIG_INVALID: minSources.');
const grades = typeof c.allowedGrades === 'string' ? c.allowedGrades.split(',').map(x => x.trim()) : [];
if (!grades.length || new Set(grades).size !== grades.length || grades.some(x => !['consensus','blended','composite','single-source','indicative'].includes(x))) throw new Error('CONFIG_INVALID: allowedGrades.');
const policy = Object.fromEntries(Object.keys(ranges).map(k => [k,c[k]]));
policy.allowedGrades = grades.sort();
const monitorKey = String($workflow.id) + ':' + c.symbol;
return [{json:{symbol:c.symbol, policy, monitorKey, policyKey:JSON.stringify(policy)},pairedItem:{item:0}}];

function toolBody(response) {
  const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
  if (!object(response) || response.error !== undefined || response.isError === true) {
    throw new Error('UNVERIFIED: the MCP call returned an error. No observation is approved.');
  }
  let body = response.structuredContent;
  if (body === undefined) {
    const content = response.content;
    if (!Array.isArray(content) || content.length !== 1 || content[0].type !== 'text') {
      throw new Error('UNVERIFIED: missing or ambiguous MCP result.');
    }
    body = content[0].text;
    if (typeof body === 'string') {
      if (body.length > 32768) throw new Error('UNVERIFIED: oversized MCP result.');
      try { body = JSON.parse(body); }
      catch { throw new Error('UNVERIFIED: the MCP result is not JSON.'); }
    }
  }
  if (!object(body) || body.error !== undefined || body.success === false || JSON.stringify(body).length > 32768) {
    throw new Error('UNVERIFIED: the MCP result is unavailable or malformed.');
  }
  return body;
}

const items = $input.all();
if (items.length !== 1) throw new Error('UNVERIFIED: expected one price result.');
const print = toolBody(items[0].json);
const requestedSymbol = $('Validate monitor settings').first().json.symbol;
const signature = /^[A-Za-z0-9+/]{86}==$/;
if (print.symbol !== requestedSymbol || typeof print.price !== 'number' || !Number.isFinite(print.price)
    || print.price <= 0 || typeof print.at !== 'string' || !Number.isFinite(Date.parse(print.at))
    || !['consensus', 'blended', 'indicative', 'composite', 'single-source'].includes(print.grade)
    || typeof print.signature !== 'string' || !signature.test(print.signature)
    || !print.v2 || print.v2.sig !== 'pulse-index-v2'
    || typeof print.v2.signature !== 'string' || !signature.test(print.v2.signature)
    || typeof print.v2.canonical !== 'string' || print.v2.canonical.length > 8192
    || typeof print.v2.kid !== 'string' || !/^[A-Za-z0-9._:-]{1,64}$/.test(print.v2.kid)) {
  throw new Error('UNVERIFIED: a complete signed price record is required.');
}
if (print.priceText !== undefined && (typeof print.priceText !== 'string' || !print.priceText.length
    || print.priceText.length > 100 || Number(print.priceText) !== print.price)) {
  throw new Error('UNVERIFIED: price and exact price text disagree.');
}
// Keep every byte of priceText and v2.canonical unchanged. The verifier takes
// the print fields at the top level, not an object nested under "print".
return [{ json: { print }, pairedItem: { item: 0 } }];

function toolBody(response) {
  const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
  if (!object(response) || response.error !== undefined || response.isError === true) {
    throw new Error('UNVERIFIED: the MCP call returned an error. No observation is approved.');
  }
  let body = response.structuredContent;
  if (body === undefined) {
    const content = response.content;
    if (!Array.isArray(content) || content.length !== 1 || content[0].type !== 'text') {
      throw new Error('UNVERIFIED: missing or ambiguous MCP result.');
    }
    body = content[0].text;
    if (typeof body === 'string') {
      if (body.length > 32768) throw new Error('UNVERIFIED: oversized MCP result.');
      try { body = JSON.parse(body); }
      catch { throw new Error('UNVERIFIED: the MCP result is not JSON.'); }
    }
  }
  if (!object(body) || body.error !== undefined || body.success === false || JSON.stringify(body).length > 32768) {
    throw new Error('UNVERIFIED: the MCP result is unavailable or malformed.');
  }
  return body;
}

const items = $input.all();
if (items.length !== 1) throw new Error('UNVERIFIED: expected one verification result.');
const result = toolBody(items[0].json);
const print = $('Preserve signed print').first().json.print;
// Strict booleans: a string "true", v1-only valid, or a missing field fails.
if (result.recordValid !== true || result.valid !== true || result.metadataSigned !== true
    || result.verificationScope !== 'full-record' || result.v2?.valid !== true
    || result.v2?.signatureValid !== true || result.v2?.fieldsMatch !== true
    || !Array.isArray(result.v2.mismatches) || result.v2.mismatches.length !== 0) {
  throw new Error('UNVERIFIED: full-record signature verification did not pass.');
}
const expectedCheck = ['pulse-index-v1', print.symbol, print.priceText ?? String(print.price), print.at, print.grade].join('\n');
if (result.checked !== expectedCheck || result.v2.verifiedWithKid !== print.v2.kid
    || (print.kid !== undefined && result.verifiedWithKid !== print.kid)) {
  throw new Error('UNVERIFIED: the verification does not match this price record.');
}
const fields = ['symbol', 'price', 'priceText', 'at', 'grade', 'engine', 'sources', 'tier',
  'confidence', 'dispersionBps', 'interval.lower', 'interval.upper', 'cadence.band',
  'cadence.calculatedAgeMs', 'cadence.newestSourceAgeMs', 'cadence.oldestSourceAgeMs',
  'cadence.p50UpdateMs', 'cadence.p95UpdateMs'];
const signed = result.v2.signedFields;
if (!signed || typeof signed !== 'object' || Array.isArray(signed)
    || Object.keys(signed).length !== fields.length) {
  throw new Error('UNVERIFIED: expected the complete live-record field set.');
}
for (const path of fields) {
  const value = path.split('.').reduce((object, key) => object?.[key], print) ?? null;
  if (!Object.prototype.hasOwnProperty.call(signed, path) || signed[path] !== value) {
    throw new Error('UNVERIFIED: signed fields differ from this observation.');
  }
}
return [{ json: {
  status: 'VERIFIED',
  source: 'Pulse Verity Index',
  verificationMeaning: 'Signatures and covered record fields match. Freshness and suitability require separate checks.',
  signedFields: signed,
  signedPrint: print,
  verification: {
    recordValid: true, verificationScope: result.verificationScope,
    verifiedWithKid: result.verifiedWithKid, v2VerifiedWithKid: result.v2.verifiedWithKid,
    performedBy: 'Hosted Pulse Verity MCP verify_print'
  }
}, pairedItem: { item: 0 } }];

const v = $input.all();
if (v.length !== 1 || v[0].json.status !== 'VERIFIED' || v[0].json.verification?.recordValid !== true) throw new Error('UNVERIFIED');
const {symbol,policy,monitorKey,policyKey} = $('Validate monitor settings').first().json;
const p = v[0].json.signedPrint;
const now = Date.now();
const ageSeconds = (now - Date.parse(p.at)) / 1000;
let reason = 'POLICY_PASS';
if (!Number.isFinite(ageSeconds)) reason = 'TIMESTAMP_INVALID';
else if (ageSeconds < -policy.maxFutureSkewSeconds) reason = 'FUTURE_TIMESTAMP';
else if (ageSeconds > policy.maxAgeSeconds) reason = 'STALE';
else if (!policy.allowedGrades.includes(p.grade)) reason = 'GRADE_REJECTED';
else if (typeof p.confidence !== 'number' || !Number.isFinite(p.confidence) || p.confidence < 0 || p.confidence > 1
 || typeof p.dispersionBps !== 'number' || !Number.isFinite(p.dispersionBps) || p.dispersionBps < 0
 || !Number.isInteger(p.sources) || p.sources < 1) reason = 'QUALITY_MISSING';
else if (p.confidence < policy.minConfidence) reason = 'LOW_CONFIDENCE';
else if (p.dispersionBps > policy.maxDispersionBps) reason = 'WIDE_DISPERSION';
else if (p.sources < policy.minSources) reason = 'INSUFFICIENT_SOURCES';
const status = reason === 'POLICY_PASS' ? 'ACCEPTED' : 'REJECTED';
return [{json:{monitorKey,policyKey,symbol,observedAt:new Date(now).toISOString(),status,reason,recordValid:true,
 priceText:p.priceText ?? String(p.price),recordAt:p.at,grade:p.grade,ageSeconds:Number.isFinite(ageSeconds)?ageSeconds:null,
 evidenceJson:JSON.stringify({recordAt:p.at,grade:p.grade,confidence:p.confidence,dispersionBps:p.dispersionBps,sources:p.sources,verification:v[0].json.verification})},pairedItem:{item:0}}];

// Deliberately discard raw provider errors, headers, bodies and credentials.
const c = $('Validate monitor settings').first().json;
return [{json:{monitorKey:c.monitorKey,policyKey:c.policyKey,symbol:c.symbol,observedAt:new Date().toISOString(),
 status:'UNAVAILABLE',reason:'READ_OR_VERIFICATION_FAILED',recordValid:false,priceText:'',recordAt:'',grade:'',ageSeconds:null,
 evidenceJson:JSON.stringify({recordValid:false,detail:'No usable fully verified record; inspect the failed stage in a controlled manual test.'})},pairedItem:{item:0}}];

const items = $input.all();
if (items.length !== 1) throw new Error('AUDIT_INVALID');
const r = items[0].json;
if (!['ACCEPTED','REJECTED','UNAVAILABLE'].includes(r.status) || typeof r.recordValid !== 'boolean') throw new Error('AUDIT_INVALID');
return [{json:{...r,executionId:String($execution.id)},pairedItem:{item:0}}];

const r = $('Prepare audit row').first().json;
const rows = $input.all().map(x => x.json).filter(x => Object.keys(x).length);
if (rows.length > 1) throw new Error('STATE_CONFLICT: duplicate monitor rows; resolve before continuing.');
const prior = rows[0];
if (prior && (prior.monitorKey !== r.monitorKey || !['ACCEPTED','REJECTED','UNAVAILABLE'].includes(prior.status) || typeof prior.reason !== 'string' || typeof prior.policyKey !== 'string')) throw new Error('STATE_INVALID');
// Repeated observations with the same status/reason/policy are quiet. The initial
// healthy observation establishes a baseline. Initial failures and recoveries alert.
const changed = !prior || prior.status !== r.status || prior.reason !== r.reason || prior.policyKey !== r.policyKey;
const notify = changed && (Boolean(prior) || r.status !== 'ACCEPTED');
const label = r.status === 'ACCEPTED' ? 'RECOVERED / POLICY PASS' : r.status;
const message = ['Pulse Verity Index monitor: '+r.symbol, label+' — '+r.reason,
 'Observed: '+r.observedAt, 'Previous state: '+(prior?.status ?? 'not established'),
 r.recordValid ? 'Full-record signature passed; consumer policy checked separately.' : 'No verified usable price. Do not substitute zero or a previous observation.',
 'Audit execution: '+r.executionId, 'An integrity check does not establish price correctness or settlement suitability.'].join('\n');
return [{json:{...r,notify,alertText:message},pairedItem:{item:0}}];
